def merge_tenant_settings(tenant_settings, global_settings):
    """合并租户级与全局级设置，租户级优先。"""
    merged = {}
    for source in (tenant_settings, global_settings):
        for key, value in source.items():
            if key not in merged:
                merged[key] = value
    return merged

