from target import merge_tenant_settings


def test_tenant_value_wins():
    assert merge_tenant_settings({"tz": "UTC+8"}, {"tz": "UTC"}) == {"tz": "UTC+8"}


def test_none_tenant_value_falls_back_to_global():
    assert merge_tenant_settings({"tz": None}, {"tz": "UTC"}) == {"tz": "UTC"}


